"use strict";(globalThis.webpackChunkgrc||=[]).push([[41613],{11578(e){e.exports=JSON.parse('{"citeKey":"khettry2000windowsnt","slug":"khettry-2000-windows-nt-464f","title":"A Windows-NT Virtual Collaboratory For Technical Computing","authors":["D. Khettry","X.-H. Sun"],"venue":"International Journal on Advances in Engineering Software, Vol. 31, pp. 717-722","type":"Journal","entryType":"article","date":"September, 2000","year":2000,"era":"iit","month":9,"doi":"10.1016/s0965-9978(00)00020-x","abstract":"Virtual Collaborative Environment (VCE) addresses enabling technologies to support collaborative, distributed, computer-based problem solving for engineering applications. The goal is to simulate a virtual laboratory, based on cooperative computing substrate, that integrally supports a shared workspace, high performance computing, distributed data management, as well as graphical scientific communication. In this study we present the design and development of a Windows-NT based VCE for technical computing.","hasAbstract":true,"lede":"In this study we present the design and development of a Windows-NT based VCE for technical computing.","links":{"pdf":"https://grc.iit.edu/papers/2000/khettry-2000-windows-nt-464f.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["vcns"],"memberAuthors":["sun-xian-he"]}')}}]);